package io.github.qisun8023.filemanager.helper;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.provider.Settings;import android.view.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
public class MonitorService extends Service {
 final Handler handler=new Handler(Looper.getMainLooper());ScheduledExecutorService executor;Dialog dialog;Set<String> notified=ConcurrentHashMap.newKeySet(),shown=ConcurrentHashMap.newKeySet();volatile boolean busy=false;NotificationManager manager;
 final java.util.concurrent.atomic.AtomicBoolean pollQueued=new java.util.concurrent.atomic.AtomicBoolean();
 final BroadcastReceiver awake=new BroadcastReceiver(){public void onReceive(Context c,Intent i){requestPoll();}};
 void requestPoll(){if(executor==null||executor.isShutdown()||!pollQueued.compareAndSet(false,true))return;try{executor.execute(()->{try{poll();}finally{pollQueued.set(false);}});}catch(RejectedExecutionException ex){pollQueued.set(false);}}
 String destination(JSONObject item){String target=item.optString("target"),name=item.optString("targetName");if(name.isEmpty()){name=new java.io.File(item.optString("path")).getName();if(name.toLowerCase(java.util.Locale.ROOT).endsWith(".apk.1"))name=name.substring(0,name.length()-6)+".apk";}return target+"/"+name;}

 public IBinder onBind(Intent i){return null;}
 public void onCreate(){super.onCreate();IntentFilter f=new IntentFilter(Intent.ACTION_USER_PRESENT);f.addAction(Intent.ACTION_SCREEN_ON);if(Build.VERSION.SDK_INT>=33)registerReceiver(awake,f,Context.RECEIVER_NOT_EXPORTED);else registerReceiver(awake,f);manager=getSystemService(NotificationManager.class);manager.createNotificationChannel(new NotificationChannel("monitor","监控运行状态",NotificationManager.IMPORTANCE_LOW));manager.createNotificationChannel(new NotificationChannel("files","新增文件询问",NotificationManager.IMPORTANCE_HIGH));}
 public int onStartCommand(Intent i,int flags,int startId){if(!getSharedPreferences("helper",0).getBoolean("reminders",true)){stopSelf();return START_NOT_STICKY;}try{startForeground(1,ongoing("正在连接模块；目录规则在 WebUI 中设置"));}catch(Exception ex){stopSelf();return START_NOT_STICKY;}if(i!=null&&i.hasExtra("decision")){String id=i.getStringExtra("id"),choice=i.getStringExtra("decision");if(id!=null&&id.matches("[a-f0-9]{32}")&&("move".equals(choice)||"keep".equals(choice)))submit(id,choice);}if(executor==null){executor=Executors.newSingleThreadScheduledExecutor();executor.scheduleWithFixedDelay(()->poll(),0,5,TimeUnit.SECONDS);}else requestPoll();return START_STICKY;}
 PendingIntent open(){return PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);}
 Notification ongoing(String text){return new Notification.Builder(this,"monitor").setSmallIcon(android.R.drawable.stat_notify_sync).setContentTitle("文件管理监控").setContentText(text).setContentIntent(open()).setOngoing(true).build();}
 PendingIntent decision(String id,String action){Intent i=new Intent(this,MonitorService.class).setAction(action).setData(android.net.Uri.parse("filemanager-helper://decision/"+id+"/"+action)).putExtra("id",id).putExtra("decision",action);return PendingIntent.getForegroundService(this,0,i,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);}
 void poll(){if(busy)return;try{JSONObject data=Root.call("watch-status",new JSONObject());if(!data.optBoolean("enabled")){handler.post(()->stopSelf());return;}if(!data.optBoolean("running")){Root.call("watch-start",new JSONObject());manager.notify(1,ongoing("正在恢复后台监控，请稍候…"));return;}JSONArray items=data.optJSONArray("items");Set<String> active=new HashSet<>();if(items!=null)for(int n=0;n<items.length();n++){JSONObject item=items.getJSONObject(n);String id=item.getString("id");active.add(id);if(!notified.contains(id)&&canNotify()){notifyItem(item);notified.add(id);}}
  for(String id:new HashSet<>(notified))if(!active.contains(id)){manager.cancel(id,2);notified.remove(id);shown.remove(id);}manager.notify(1,ongoing("待处理 "+active.size()+" 个文件；点击检查提醒权限"));
  if(items!=null&&items.length()>0)handler.post(()->offer(items));
 }catch(Exception ex){try{manager.notify(1,ongoing("连接失败：请打开助手检查 Root 授权"));}catch(Exception ignored){}}}
 boolean canNotify(){return (Build.VERSION.SDK_INT<33||checkSelfPermission("android.permission.POST_NOTIFICATIONS")==PackageManager.PERMISSION_GRANTED)&&manager.areNotificationsEnabled();}
 void notifyItem(JSONObject item)throws Exception{String id=item.getString("id"),path=item.getString("path"),target=destination(item);String text="来源："+path+"\n转移至："+target+(item.optBoolean("verified")?"\n已通过压缩包完整性检查":"\n按文件稳定时间判断，请核对是否已下载完成");Notification n=new Notification.Builder(this,"files").setSmallIcon(android.R.drawable.stat_sys_download_done).setContentTitle("是否转移 "+new java.io.File(path).getName()+"？").setContentText(target).setStyle(new Notification.BigTextStyle().bigText(text)).setContentIntent(open()).setAutoCancel(false).addAction(new Notification.Action.Builder(null,"转移",decision(id,"move")).build()).addAction(new Notification.Action.Builder(null,"保留原处",decision(id,"keep")).build()).build();manager.notify(id,2,n);}
 void offer(JSONArray items){if(dialog!=null||busy||!Settings.canDrawOverlays(this))return;PowerManager power=getSystemService(PowerManager.class);KeyguardManager keyguard=getSystemService(KeyguardManager.class);if(!power.isInteractive()||keyguard.isKeyguardLocked())return;
  for(int n=items.length()-1;n>=0;n--){JSONObject item=items.optJSONObject(n);if(item==null)continue;String id=item.optString("id");if(shown.contains(id))continue;shown.add(id);String path=item.optString("path");dialog=MiuixPrompt.create(this,new java.io.File(path).getName(),path,destination(item),item.optBoolean("verified"),choice->submit(id,choice));dialog.setOnDismissListener(d->dialog=null);try{dialog.show();}catch(Exception ex){dialog=null;}return;
  }
 }
 void submit(String id,String choice){busy=true;new Thread(()->{try{Root.call("watch-decide",new JSONObject().put("id",id).put("decision",choice));manager.cancel(id,2);handler.post(()->android.widget.Toast.makeText(this,"move".equals(choice)?"已转移":"已保留原处",1).show());}catch(Exception ex){handler.post(()->android.widget.Toast.makeText(this,ex.getMessage(),1).show());shown.remove(id);}finally{busy=false;}}).start();}
 public void onDestroy(){try{unregisterReceiver(awake);}catch(IllegalArgumentException ignored){}if(executor!=null)executor.shutdownNow();handler.removeCallbacksAndMessages(null);if(dialog!=null)dialog.dismiss();stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}
}
